import{describe,it,expect}from"vitest";import{primeMinisters,filterPMData,getPartyBadgeClass,calculateStats}from"../../frontend/governance/prime-ministers/script.js";describe("Prime Ministers of India Timeline",()=>{it("should contain a complete dataset of Prime Ministers of India from 1947 to Present",()=>{expect(Array.isArray(primeMinisters)).toBe(!0),expect(primeMinisters.length).toBeGreaterThanOrEqual(15),primeMinisters.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("number"),expect(e).toHaveProperty("name"),expect(e).toHaveProperty("party"),expect(e).toHaveProperty("partyCategory"),expect(e).toHaveProperty("start"),expect(e).toHaveProperty("end"),expect(e).toHaveProperty("termDuration"),expect(e).toHaveProperty("portrait"),expect(e).toHaveProperty("bio"),expect(e).toHaveProperty("achievements"),expect(Array.isArray(e.achievements)).toBe(!0),expect(e.achievements.length).toBeGreaterThan(0),expect(e).toHaveProperty("events"),expect(Array.isArray(e.events)).toBe(!0),expect(e.events.length).toBeGreaterThan(0),expect(e).toHaveProperty("facts"),expect(Array.isArray(e.facts)).toBe(!0),expect(e.facts.length).toBeGreaterThan(0)})}),it("should filter Prime Minister data by search query",()=>{const e=filterPMData(primeMinisters,"Nehru");expect(e.length).toBeGreaterThanOrEqual(1),expect(e[0].name).toContain("Jawaharlal Nehru");const t=filterPMData(primeMinisters,"Modi");expect(t.length).toBe(1),expect(t[0].name).toBe("Narendra Modi");const r=filterPMData(primeMinisters,"Pokhran");expect(r.length).toBeGreaterThanOrEqual(2)}),it("should filter Prime Minister data by political party category",()=>{const e=filterPMData(primeMinisters,"","BJP");expect(e.length).toBeGreaterThanOrEqual(3),e.forEach(e=>expect(e.partyCategory).toBe("BJP"));const t=filterPMData(primeMinisters,"","INC");expect(t.length).toBeGreaterThanOrEqual(5),t.forEach(e=>expect(e.partyCategory).toBe("INC"));const r=filterPMData(primeMinisters,"","Janata Party");expect(r.length).toBeGreaterThanOrEqual(2),r.forEach(e=>expect(e.partyCategory).toBe("Janata Party"))}),it("should return correct party badge CSS class names",()=>{expect(getPartyBadgeClass("INC")).toBe("party-inc"),expect(getPartyBadgeClass("BJP")).toBe("party-bjp"),expect(getPartyBadgeClass("Janata Party")).toBe("party-janata"),expect(getPartyBadgeClass("Janata Dal")).toBe("party-dal"),expect(getPartyBadgeClass("Independent")).toBe("party-other")}),it("should calculate summary statistics correctly",()=>{const e=calculateStats(primeMinisters);expect(e.totalTerms).toBe(primeMinisters.length),expect(e.uniquePrimeMinisters).toBe(15),expect(e.partyCounts).toHaveProperty("INC"),expect(e.partyCounts).toHaveProperty("BJP")})});